679	  const { retry } = binding.compensation;
680	  let lastReason = null;
681	
682	  for (let attempt = 1; attempt <= retry.attempts; attempt += 1) {
683	    const inputCopy = structuredClone(snapshot.input);
684	    const outputCopy = structuredClone(snapshot.output);
685	    const resultCopy = structuredClone(snapshot.result);
686	    const record = {
687	      nodeId, operation: binding.compensation.name, attempt,
688	      ok: false, error: null, nextDelayMs: 0, result: null,
689	    };
690	    let returned;
691	    try {
692	      returned = await implementation(inputCopy, outputCopy, resultCopy, nodeId, attempt);
693	    } catch (error) {
